pare(\"SELECT * FROM folders WHERE id = ? AND user_id = ?\");\n  const findBookmarksByFolderId = db.prepare(\n    \"SELECT * FROM bookmarks WHERE folder_id = ? AND user_id = ? ORDER BY id ASC\",\n  );\n\n  router.post(\"/\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const name = readNonEmptyString(req.body?.name);\n\n    if (!name) {\n      return res.status(400).json({ error: \"name must be a non-empty string\" });\n    }\n\n    const now = new Date().toISOString();\n    const result = db\n      .prepare(\n        `\n          INSERT INTO folders (user_id, name, created_at, updated_at)\n          VALUES (?, ?, ?, ?)\n        `,\n      )\n      .run(userId, name, now, now);\n\n    const folder = findById.get(result.lastInsertRowid, userId) as FolderRow;\n\n    return res.status(201).json(toFolderResponse(folder));\n  });\n\n  router.get(\"/\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const folders = db\n      .prepare(\"SELECT * FROM folders WHERE user_id = ? ORDER BY id ASC\")\n      .all(userId) as FolderRow[];\n\n    return res.status(200).json(folders.map(toFolderResponse));\n  });\n\n  router.get(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const folder = findById.get(id, userId) as FolderRow | undefined;\n    if (!folder) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    const bookmarks = findBookmarksByFolderId.all(id, userId) as BookmarkRow[];\n    const response: FolderWithBookmarksResponse = {\n      ...toFolderResponse(folder),\n      bookmarks: bookmarks.map(toBookmarkResponse),\n    };\n\n    return res.status(200).json(response);\n  });\n\n  router.put(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const existing = findById.get(id, userId) as FolderRow | undefined;\n    if (!existing) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    const name =\n      req.body?.name === undefined ? existing.name : readNonEmptyString(req.body.name);\n    if (!name) {\n      return res.status(400).json({ error: \"name must be a non-empty string\" });\n    }\n\n    const updatedAt = new Date().toISOString();\n    db.prepare(\"UPDATE folders SET name = ?, updated_at = ? WHERE id = ? AND user_id = ?\").run(\n      name,\n      updatedAt,\n      id,\n      userId,\n    );\n\n    const updated = findById.get(id, userId) as FolderRow;\n\n    return res.status(200).json(toFolderResponse(updated));\n  });\n\n  router.delete(\"/:id\", (req, res) => {\n    const userId = getAuthenticatedUserId(req);\n    const id = getFolderId(req, res);\n    if (id === null) {\n      return;\n    }\n\n    const result = db.prepare(\"DELETE FROM folders WHERE id = ? AND user_id = ?\").run(\n      id,\n      userId,\n    );\n    if (result.changes === 0) {\n      return res.status(404).json({ error: \"Folder not found\" });\n    }\n\n    return res.status(204).send();\n  });\n\n  return router;\n};\n","exit_code":0,"status":"completed"}}
