./benchmark/runs/baseline-main-20260526/T4-authentication/events.jsonl:27:{"type":"item.completed","item":{"id":"item_12","type":"command_execution","command":"/bin/zsh -lc \"sed -n '1,360p' src/bookmarks.ts\"","aggregated_output":"import { Router } from \"express\";\nimport { getDb } from \"./database\";\n\ntype Bookmark = {\n  id: number;\n  url: string;\n  title: string;\n  description: string | null;\n  folder_id: number | null;\n  created_at: string;\n  updated_at: string;\n};\n\ntype BookmarkInput = {\n  url?: unknown;\n  title?: unknown;\n  description?: unknown;\n  folder_id?: unknown;\n};\n\nconst router = Router();\nconst db = getDb();\n\nconst findBookmark = db\n  .prepare(\"SELECT id, url, title, description, folder_id, created_at, updated_at FROM bookmarks WHERE id = ?\")\n  .pluck(false);\n\nconst listBookmarks = db.prepare(\n  \"SELECT id, url, title, description, folder_id, created_at, updated_at FROM bookmarks ORDER BY id ASC\",\n);\n\nconst insertBookmark = db.prepare(`\n  INSERT INTO bookmarks (url, title, description, folder_id, created_at, updated_at)\n  VALUES (@url, @title, @description, @folder_id, @created_at, @updated_at)\n`);\n\nconst updateBookmark = db.prepare(`\n  UPDATE bookmarks\n  SET url = @url,\n      title = @title,\n      description = @description,\n      folder_id = @folder_id,\n      updated_at = @updated_at\n  WHERE id = @id\n`);\n\nconst deleteBookmark = db.prepare(\"DELETE FROM bookmarks WHERE id = ?\");\nconst findFolder = db.prepare(\"SELECT id FROM folders WHERE id = ?\");\n\nfunction getBookmark(id: number): Bookmark | undefined {\n  return findBookmark.get(id) as Bookmark | undefined;\n}\n\nfunction parseId(value: string): number | undefined {\n  const id = Number(value);\n  return Number.isInteger(id) && id > 0 ? id : undefined;\n}\n\nfunction textField(value: unknown): string | undefined {\n  return typeof value === \"string\" ? value.trim() : undefined;\n}\n\nfunction parseDescription(value: unknown): string | null {\n  if (value === undefined || value === null) {\n    return null;\n  }\n\n  return typeof value === \"string\" ? value : String(value);\n}\n\nfunction parseFolderId(value: unknown): number | null | undefined {\n  if (value === undefined) {\n    return undefined;\n  }\n\n  if (value === null) {\n    return null;\n  }\n\n  if (typeof value !== \"number\" || !Number.isInteger(value) || value <= 0) {\n    return undefined;\n  }\n\n  return value;\n}\n\nfunction folderExists(folderId: number): boolean {\n  return Boolean(findFolder.get(folderId));\n}\n\nfunction validateFolderId(value: unknown): { folder_id: number | null | undefined } | { error: string } {\n  const folderId = parseFolderId(value);\n\n  if (folderId === undefined && value !== undefined) {\n    return { error: \"folder_id must reference an existing folder\" };\n  }\n\n  if (folderId !== null && folderId !== undefined && !folderExists(folderId)) {\n    return { error: \"folder_id must reference an existing folder\" };\n  }\n\n  return { folder_id: folderId };\n}\n\nfunction validateRequiredBookmark(\n  input: BookmarkInput,\n): { url: string; title: string; description: string | null; folder_id: number | null } | { error: string } {\n  const url = textField(input.url);\n  const title = textField(input.title);\n\n  if (!url) {\n    return { error: \"url is required\" };\n  }\n\n  if (!title) {\n    return { error: \"title is required\" };\n  }\n\n  const folder = validateFolderId(input.folder_id);\n  if (\"error\" in folder) {\n    return folder;\n  }\n\n  return {\n    url,\n    title,\n    description: parseDescription(input.description),\n    folder_id: folder.folder_id ?? null,\n  };\n}\n\nrouter.post(\"/\", (req, res) => {\n  const parsed = validateRequiredBookmark(req.body as BookmarkInput);\n\n  if (\"error\" in parsed) {\n    res.status(400).json({ error: parsed.error });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const result = insertBookmark.run({\n    url: parsed.url,\n    title: parsed.title,\n    description: parsed.description,\n    folder_id: parsed.folder_id,\n    created_at: now,\n    updated_at: now,\n  });\n\n  const bookmark = getBookmark(Number(result.lastInsertRowid));\n  res.status(201).json(bookmark);\n});\n\nrouter.get(\"/\", (_req, res) => {\n  res.status(200).json(listBookmarks.all() as Bookmark[]);\n});\n\nrouter.get(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const bookmark = id ? getBookmark(id) : undefined;\n\n  if (!bookmark) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(200).json(bookmark);\n});\n\nrouter.put(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const current = id ? getBookmark(id) : undefined;\n\n  if (!id || !current) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  const input = req.body as BookmarkInput;\n  const url = input.url === undefined ? current.url : textField(input.url);\n  const title = input.title === undefined ? current.title : textField(input.title);\n\n  if (!url) {\n    res.status(400).json({ error: \"url is required\" });\n    return;\n  }\n\n  if (!title) {\n    res.status(400).json({ error: \"title is required\" });\n    return;\n  }\n\n  const folder = validateFolderId(input.folder_id);\n  if (\"error\" in folder) {\n    res.status(400).json({ error: folder.error });\n    return;\n  }\n\n  updateBookmark.run({\n    id,\n    url,\n    title,\n    description: input.description === undefined ? current.description : parseDescription(input.description),\n    folder_id: folder.folder_id === undefined ? current.folder_id : folder.folder_id,\n    updated_at: new Date().toISOString(),\n  });\n\n  res.status(200).json(getBookmark(id));\n});\n\nrouter.delete(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const result = id ? deleteBookmark.run(id) : { changes: 0 };\n\n  if (result.changes === 0) {\n    res.status(404).json({ error: \"bookmark not found\" });\n    return;\n  }\n\n  res.status(204).send();\n});\n\nexport default router;\n","exit_code":0,"status":"completed"}}
