r: Folder): Folder & { bookmarks: Bookmark[] } {\n  return {\n    ...folder,\n    bookmarks: listFolderBookmarks.all(folder.id) as Bookmark[],\n  };\n}\n\nrouter.post(\"/\", (req, res) => {\n  const name = parseName((req.body as FolderInput).name);\n\n  if (!name) {\n    res.status(400).json({ error: \"name is required\" });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const result = insertFolder.run({\n    name,\n    created_at: now,\n    updated_at: now,\n  });\n\n  res.status(201).json(getFolder(Number(result.lastInsertRowid)));\n});\n\nrouter.get(\"/\", (_req, res) => {\n  res.status(200).json(listFolders.all() as Folder[]);\n});\n\nrouter.get(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const folder = id ? getFolder(id) : undefined;\n\n  if (!folder) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  res.status(200).json(folderWithBookmarks(folder));\n});\n\nrouter.put(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const folder = id ? getFolder(id) : undefined;\n\n  if (!id || !folder) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const name = parseName((req.body as FolderInput).name);\n\n  if (!name) {\n    res.status(400).json({ error: \"name is required\" });\n    return;\n  }\n\n  updateFolder.run({\n    id,\n    name,\n    updated_at: new Date().toISOString(),\n  });\n\n  res.status(200).json(getFolder(id));\n});\n\nrouter.delete(\"/:id\", (req, res) => {\n  const id = parseId(req.params.id);\n  const folder = id ? getFolder(id) : undefined;\n\n  if (!id || !folder) {\n    res.status(404).json({ error: \"folder not found\" });\n    return;\n  }\n\n  const now = new Date().toISOString();\n  const transaction = db.transaction((folderId: number) => {\n    unfolderBookmarks.run({ folder_id: folderId, updated_at: now });\n    deleteFolder.run(folderId);\n  });\n\n  transaction(id);\n  res.status(204).send();\n});\n\nexport defaul